/**
 * File: scripts/migrate-module-overhaul.js
 * Purpose: Phase 2 schema migration for the Module -> Handout -> Assessment
 *          overhaul. See MODULE_OVERHAUL_PLAN.md.
 *
 * Run:  node scripts/migrate-module-overhaul.js                  (uses .env)
 *       node scripts/migrate-module-overhaul.js --env .env.live  (uses that file)
 *
 * Safety:
 *  - Every step is guarded, so the whole script is safe to re-run. A second run
 *    reports "skip" for everything and changes nothing.
 *  - CHECK/UNIQUE constraint names in this database are auto-generated by SQL
 *    Server (e.g. CK__modules__level__2EF0D041) and therefore DIFFER between
 *    the local and live databases. Every constraint drop looks the name up from
 *    sys.* at runtime instead of hardcoding it.
 *  - It runs against whatever DB_HOST is in .env. Confirm which database you are
 *    pointed at before running; back the database up first when that is live.
 *
 * What it changes:
 *  1. subjects.handout_version        -> cache key that drives regenerate-vs-reuse
 *  2. modules.order_number            -> Module 1, 2, 3... unlimited per subject
 *  3. modules.target_year_levels_json -> which year levels a module is visible to
 *  4. modules: drop UNIQUE(subject_id, level) and the level CHECK, make level
 *     nullable. level used to cap a subject at 3 modules (one per level); it is
 *     now vestigial and kept only so legacy rows still read.
 *  5. module_handouts                 -> NEW: many handout files per module,
 *     with an extracted_text cache so a file is parsed once, not per request
 *  6. tutor_assessments: module_id becomes nullable (pre/post are subject-level,
 *     spanning all modules) + assessment_kind, question_type, item_count,
 *     source_pre_assessment_id, handout_version
 *  7. tutor_assessment_questions: allow 'essay' + carry source_module_id /
 *     source_handout_id / answer_rubric for weak-area traceability
 *  8. Classification alignment: standardise on 'Advance' (the spelling the spec
 *     and assessment_results/assessment_attempts already use). student_subject_levels
 *     and modules used 'Advanced', which meant the same score produced a value one
 *     table would reject.
 */

// Which environment file to read. Deploying means running this against the live
// database, and editing .env to do that — then forgetting to change it back — is
// exactly how a migration lands on the wrong server.
const envArgIndex = process.argv.indexOf('--env');
const envFile = envArgIndex > -1 ? process.argv[envArgIndex + 1] : '.env';
require('dotenv').config({ path: envFile });

const { getPool } = require('../config/db');

let pool;
const results = { applied: 0, skipped: 0, failed: 0 };

/** Run `sql` only when `check` returns a truthy first column. */
async function step(label, checkSql, sql) {
  try {
    if (checkSql) {
      const r = await pool.request().query(checkSql);
      const row = r.recordset && r.recordset[0];
      const needed = row ? Object.values(row)[0] : 0;
      if (!needed) {
        console.log(`  skip     ${label}`);
        results.skipped++;
        return;
      }
    }
    await pool.request().query(sql);
    console.log(`  applied  ${label}`);
    results.applied++;
  } catch (error) {
    console.error(`  FAILED   ${label}\n           ${error.message}`);
    results.failed++;
  }
}

/**
 * Drop the CHECK constraint on a column, whatever SQL Server auto-named it.
 *
 * `keepName` is the constraint this migration installs itself. Without it, a
 * re-run would drop the correct new constraint and re-add it every time — the
 * end state would be right but the script would not be idempotent, and it would
 * churn constraints on the live database for no reason.
 */
async function dropColumnCheck(table, column, keepName = null) {
  const label = `drop CHECK on ${table}.${column}`;
  try {
    const r = await pool.request().query(`
      SELECT dc.name
      FROM sys.check_constraints dc
      JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id
      WHERE dc.parent_object_id = OBJECT_ID('dbo.${table}') AND c.name = '${column}'`);
    const stale = r.recordset.filter((row) => row.name !== keepName);
    if (!stale.length) {
      console.log(`  skip     ${label} (nothing stale)`);
      results.skipped++;
      return;
    }
    for (const row of stale) {
      await pool.request().query(`ALTER TABLE dbo.${table} DROP CONSTRAINT [${row.name}]`);
      console.log(`  applied  ${label} (${row.name})`);
      results.applied++;
    }
  } catch (error) {
    console.error(`  FAILED   ${label}\n           ${error.message}`);
    results.failed++;
  }
}

/**
 * Drop the DEFAULT constraint on a column. SQL Server blocks ALTER COLUMN while
 * one is attached, and the name is auto-generated so it differs per database.
 */
async function dropColumnDefault(table, column, keepName = null) {
  const label = `drop DEFAULT on ${table}.${column}`;
  try {
    const r = await pool.request().query(`
      SELECT dc.name
      FROM sys.default_constraints dc
      JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id
      WHERE dc.parent_object_id = OBJECT_ID('dbo.${table}') AND c.name = '${column}'`);
    // Skip the default this migration installs itself, or a re-run would drop and
    // re-add it every time instead of reporting a clean no-op.
    const stale = r.recordset.filter((row) => row.name !== keepName);
    if (!stale.length) {
      console.log(`  skip     ${label} (nothing stale)`);
      results.skipped++;
      return;
    }
    for (const row of stale) {
      await pool.request().query(`ALTER TABLE dbo.${table} DROP CONSTRAINT [${row.name}]`);
      console.log(`  applied  ${label} (${row.name})`);
      results.applied++;
    }
  } catch (error) {
    console.error(`  FAILED   ${label}\n           ${error.message}`);
    results.failed++;
  }
}

async function main() {
  pool = await getPool();
  const info = await pool.request().query('SELECT DB_NAME() AS db, @@SERVERNAME AS srv');
  console.log('Module overhaul migration (Phase 2)');
  console.log(`Database: ${info.recordset[0].db}  on  ${process.env.DB_HOST}`);
  console.log('');

  // ---------------------------------------------------------------- subjects
  console.log('subjects');
  await step(
    'subjects.handout_version',
    `SELECT CASE WHEN COL_LENGTH('dbo.subjects','handout_version') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.subjects ADD handout_version INT NOT NULL CONSTRAINT df_subjects_handout_version DEFAULT 1`
  );

  // ----------------------------------------------------------------- modules
  console.log('\nmodules');
  await step(
    'modules.order_number',
    `SELECT CASE WHEN COL_LENGTH('dbo.modules','order_number') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.modules ADD order_number INT NULL`
  );
  await step(
    'modules.target_year_levels_json',
    `SELECT CASE WHEN COL_LENGTH('dbo.modules','target_year_levels_json') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.modules ADD target_year_levels_json NVARCHAR(MAX) NULL`
  );

  // The UNIQUE(subject_id, level) constraint is what limited a subject to one
  // module per level. It also indexes `level`, so it must go before `level` can
  // be made nullable.
  await step(
    'drop UNIQUE(subject_id, level) on modules',
    `SELECT COUNT(*) AS needed FROM sys.key_constraints
      WHERE parent_object_id = OBJECT_ID('dbo.modules') AND name = 'uniq_module_subject_level'`,
    `ALTER TABLE dbo.modules DROP CONSTRAINT uniq_module_subject_level`
  );
  await dropColumnCheck('modules', 'level');
  await step(
    "modules.level data: 'Advanced' -> 'Advance'",
    `SELECT COUNT(*) AS needed FROM dbo.modules WHERE level = 'Advanced'`,
    `UPDATE dbo.modules SET level = 'Advance' WHERE level = 'Advanced'`
  );
  await step(
    'modules.level -> nullable',
    `SELECT CASE WHEN EXISTS (
       SELECT 1 FROM sys.columns
       WHERE object_id = OBJECT_ID('dbo.modules') AND name = 'level' AND is_nullable = 0
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.modules ALTER COLUMN level NVARCHAR(20) NULL`
  );
  await step(
    'backfill modules.order_number',
    `SELECT COUNT(*) AS needed FROM dbo.modules WHERE order_number IS NULL`,
    `WITH numbered AS (
       SELECT id, ROW_NUMBER() OVER (PARTITION BY subject_id ORDER BY created_at, id) AS rn
       FROM dbo.modules
     )
     UPDATE m SET m.order_number = n.rn
     FROM dbo.modules m JOIN numbered n ON n.id = m.id
     WHERE m.order_number IS NULL`
  );

  // ---------------------------------------------------------- module_handouts
  console.log('\nmodule_handouts');
  await step(
    'create table module_handouts',
    `SELECT CASE WHEN OBJECT_ID('dbo.module_handouts','U') IS NULL THEN 1 ELSE 0 END AS needed`,
    `CREATE TABLE dbo.module_handouts (
       id INT IDENTITY(1,1) PRIMARY KEY,
       module_id INT NOT NULL,
       title NVARCHAR(200) NULL,
       file_path NVARCHAR(500) NOT NULL,
       file_original_name NVARCHAR(255) NULL,
       file_type NVARCHAR(120) NULL,
       file_size_bytes INT NULL,
       extracted_text NVARCHAR(MAX) NULL,
       extracted_at DATETIME2 NULL,
       extraction_error NVARCHAR(500) NULL,
       uploaded_by INT NULL,
       is_archived BIT NOT NULL DEFAULT 0,
       created_at DATETIME2 NOT NULL DEFAULT DATEADD(hour, 8, GETUTCDATE()),
       updated_at DATETIME2 NOT NULL DEFAULT DATEADD(hour, 8, GETUTCDATE()),
       CONSTRAINT fk_mh_module FOREIGN KEY (module_id) REFERENCES dbo.modules(id) ON DELETE CASCADE,
       CONSTRAINT fk_mh_uploader FOREIGN KEY (uploaded_by) REFERENCES dbo.users(id) ON DELETE NO ACTION
     )`
  );
  await step(
    'index module_handouts(module_id)',
    `SELECT CASE WHEN OBJECT_ID('dbo.module_handouts','U') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.module_handouts') AND name = 'ix_mh_module')
       THEN 1 ELSE 0 END AS needed`,
    `CREATE INDEX ix_mh_module ON dbo.module_handouts(module_id) WHERE is_archived = 0`
  );

  await step(
    'module_handouts.extraction_method',
    `SELECT CASE WHEN OBJECT_ID('dbo.module_handouts','U') IS NOT NULL
       AND COL_LENGTH('dbo.module_handouts','extraction_method') IS NULL THEN 1 ELSE 0 END AS needed`,
    // 'text' = read from the file's own text layer; 'ocr' = the file is a scan and
    // its pages were transcribed by the vision model.
    `ALTER TABLE dbo.module_handouts ADD extraction_method NVARCHAR(20) NULL`
  );

  // -------------------------------------------------------- tutor_assessments
  console.log('\ntutor_assessments');
  // Pre/Post assessments belong to a SUBJECT and span every module, so module_id
  // has to accept NULL. The FK indexes the column, so drop and re-add it.
  await step(
    'drop fk_ta_module',
    `SELECT CASE WHEN EXISTS (
       SELECT 1 FROM sys.foreign_keys WHERE name = 'fk_ta_module' AND parent_object_id = OBJECT_ID('dbo.tutor_assessments')
     ) AND EXISTS (
       SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('dbo.tutor_assessments') AND name = 'module_id' AND is_nullable = 0
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments DROP CONSTRAINT fk_ta_module`
  );
  await step(
    'tutor_assessments.module_id -> nullable',
    `SELECT CASE WHEN EXISTS (
       SELECT 1 FROM sys.columns
       WHERE object_id = OBJECT_ID('dbo.tutor_assessments') AND name = 'module_id' AND is_nullable = 0
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments ALTER COLUMN module_id INT NULL`
  );
  await step(
    're-add fk_ta_module',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.foreign_keys WHERE name = 'fk_ta_module' AND parent_object_id = OBJECT_ID('dbo.tutor_assessments')
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments
       ADD CONSTRAINT fk_ta_module FOREIGN KEY (module_id) REFERENCES dbo.modules(id) ON DELETE NO ACTION`
  );
  await step(
    'tutor_assessments.assessment_kind',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessments','assessment_kind') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments
       ADD assessment_kind NVARCHAR(30) NOT NULL
       CONSTRAINT df_ta_kind DEFAULT 'tutor_assessment'`
  );
  await step(
    'CHECK on tutor_assessments.assessment_kind',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessments','assessment_kind') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM sys.check_constraints WHERE name = 'CK_ta_assessment_kind' AND parent_object_id = OBJECT_ID('dbo.tutor_assessments'))
       THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments ADD CONSTRAINT CK_ta_assessment_kind
       CHECK (assessment_kind IN ('pre_assessment','tutor_assessment','post_assessment'))`
  );
  await step(
    'tutor_assessments.question_type',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessments','question_type') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments ADD question_type NVARCHAR(30) NULL`
  );
  await step(
    'tutor_assessments.item_count',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessments','item_count') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments ADD item_count INT NULL`
  );
  await step(
    'tutor_assessments.source_pre_assessment_id',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessments','source_pre_assessment_id') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments ADD source_pre_assessment_id INT NULL`
  );
  await step(
    'tutor_assessments.handout_version',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessments','handout_version') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments ADD handout_version INT NULL`
  );
  // Existing rows only carried `purpose`. Map it onto the new kind so legacy
  // rows keep working instead of all defaulting to 'tutor_assessment'.
  await step(
    'backfill assessment_kind from purpose',
    `SELECT COUNT(*) AS needed FROM dbo.tutor_assessments
      WHERE assessment_kind = 'tutor_assessment' AND purpose IN ('pre','post')`,
    `UPDATE dbo.tutor_assessments
       SET assessment_kind = CASE purpose WHEN 'pre' THEN 'pre_assessment' ELSE 'post_assessment' END
     WHERE assessment_kind = 'tutor_assessment' AND purpose IN ('pre','post')`
  );

  // A generated Pre/Post assessment has no author — it is produced by the system
  // from handouts, and it spans students who may have different tutors. tutor_id
  // was NOT NULL, which would have forced us to invent an owner.
  await step(
    'drop fk_ta_tutor',
    `SELECT CASE WHEN EXISTS (
       SELECT 1 FROM sys.foreign_keys WHERE name = 'fk_ta_tutor' AND parent_object_id = OBJECT_ID('dbo.tutor_assessments')
     ) AND EXISTS (
       SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('dbo.tutor_assessments') AND name = 'tutor_id' AND is_nullable = 0
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments DROP CONSTRAINT fk_ta_tutor`
  );
  await step(
    'tutor_assessments.tutor_id -> nullable',
    `SELECT CASE WHEN EXISTS (
       SELECT 1 FROM sys.columns
       WHERE object_id = OBJECT_ID('dbo.tutor_assessments') AND name = 'tutor_id' AND is_nullable = 0
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments ALTER COLUMN tutor_id INT NULL`
  );
  await step(
    're-add fk_ta_tutor',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.foreign_keys WHERE name = 'fk_ta_tutor' AND parent_object_id = OBJECT_ID('dbo.tutor_assessments')
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessments
       ADD CONSTRAINT fk_ta_tutor FOREIGN KEY (tutor_id) REFERENCES dbo.users(id) ON DELETE NO ACTION`
  );

  // One live Pre-Assessment per subject per handout version. This is the DB-level
  // guarantee behind regenerate-vs-reuse: if two students open the subject at the
  // same moment, the second insert fails and that request re-reads the first one's
  // result instead of paying for a duplicate generation.
  await step(
    'unique live pre-assessment per subject+handout_version',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.tutor_assessments') AND name = 'uq_ta_pre_per_version'
     ) THEN 1 ELSE 0 END AS needed`,
    `CREATE UNIQUE INDEX uq_ta_pre_per_version
       ON dbo.tutor_assessments(subject_id, handout_version)
       WHERE assessment_kind = 'pre_assessment' AND is_archived = 0`
  );

  // ----------------------------------------------- tutor_assessment_questions
  console.log('\ntutor_assessment_questions');
  // The old CHECK rejected 'essay' outright, so the spec's essay questions could
  // not be stored at all.
  await dropColumnCheck('tutor_assessment_questions', 'question_type', 'CK_taq_question_type');
  await step(
    'CHECK on question_type incl. essay',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.check_constraints WHERE name = 'CK_taq_question_type' AND parent_object_id = OBJECT_ID('dbo.tutor_assessment_questions')
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_questions ADD CONSTRAINT CK_taq_question_type
       CHECK (question_type IN ('multiple_choice','true_false','fill_blank','essay'))`
  );
  // Weak-area traceability. Deliberately plain indexed INTs, not FKs: a handout
  // can be deleted while its questions live on, and SQL Server rejects the
  // ON DELETE SET NULL path here because subjects -> modules -> module_handouts
  // already cascades. Readers LEFT JOIN, so a missing source degrades to
  // "unknown source" instead of erroring.
  await step(
    'tutor_assessment_questions.source_module_id',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_questions','source_module_id') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_questions ADD source_module_id INT NULL`
  );
  await step(
    'tutor_assessment_questions.source_handout_id',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_questions','source_handout_id') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_questions ADD source_handout_id INT NULL`
  );
  await step(
    'tutor_assessment_questions.answer_rubric',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_questions','answer_rubric') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_questions ADD answer_rubric NVARCHAR(MAX) NULL`
  );
  await step(
    'index tutor_assessment_questions(source_handout_id)',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_questions','source_handout_id') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.tutor_assessment_questions') AND name = 'ix_taq_source_handout')
       THEN 1 ELSE 0 END AS needed`,
    `CREATE INDEX ix_taq_source_handout ON dbo.tutor_assessment_questions(source_handout_id)`
  );

  // ------------------------------------- attempts (AssessmentAttempt in spec)
  console.log('\ntutor_assessment_submissions / tutor_student_answers');
  await step(
    'tutor_assessment_submissions.level',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_submissions','level') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_submissions ADD level NVARCHAR(20) NULL`
  );
  await step(
    'CHECK on tutor_assessment_submissions.level',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_submissions','level') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM sys.check_constraints WHERE name = 'CK_tas_level' AND parent_object_id = OBJECT_ID('dbo.tutor_assessment_submissions'))
       THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_submissions ADD CONSTRAINT CK_tas_level
       CHECK (level IS NULL OR level IN ('Beginner','Intermediate','Advance'))`
  );
  await step(
    'tutor_assessment_submissions.started_at',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_submissions','started_at') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_submissions ADD started_at DATETIME2 NULL`
  );
  await step(
    'tutor_assessment_submissions.time_spent_seconds',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_assessment_submissions','time_spent_seconds') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_assessment_submissions ADD time_spent_seconds INT NULL`
  );
  // Only one submission per student per assessment, enforced by the DB rather
  // than by a read-then-insert check that two concurrent submits could both pass.
  await step(
    'unique submission per student+assessment',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.tutor_assessment_submissions') AND name = 'uq_tas_student_assessment'
     ) THEN 1 ELSE 0 END AS needed`,
    `CREATE UNIQUE INDEX uq_tas_student_assessment
       ON dbo.tutor_assessment_submissions(assessment_id, student_id)`
  );
  // AI essay grading returns a score AND short feedback. Without somewhere to put
  // the feedback it would be computed and thrown away.
  await step(
    'tutor_student_answers.ai_feedback',
    `SELECT CASE WHEN COL_LENGTH('dbo.tutor_student_answers','ai_feedback') IS NULL THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_student_answers ADD ai_feedback NVARCHAR(MAX) NULL`
  );
  // points_earned was INT, but AI essay grading produces fractional credit.
  // SQL Server refuses ALTER COLUMN while a DEFAULT constraint references the
  // column, so the default has to come off first. Its name is auto-generated
  // (DF__tutor_stu__point__57F2E5D4) and therefore differs per database, so it is
  // resolved from sys.default_constraints at runtime.
  await dropColumnDefault('tutor_student_answers', 'points_earned', 'df_tsa_points_earned');
  await step(
    'tutor_student_answers.points_earned -> DECIMAL',
    `SELECT CASE WHEN EXISTS (
       SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
       WHERE c.object_id = OBJECT_ID('dbo.tutor_student_answers') AND c.name = 'points_earned' AND t.name = 'int'
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_student_answers ALTER COLUMN points_earned DECIMAL(6,2) NOT NULL`
  );
  await step(
    'restore default 0 on points_earned',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.default_constraints dc
       JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id
       WHERE dc.parent_object_id = OBJECT_ID('dbo.tutor_student_answers') AND c.name = 'points_earned'
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.tutor_student_answers
       ADD CONSTRAINT df_tsa_points_earned DEFAULT 0 FOR points_earned`
  );

  // ------------------------------------------------ classification alignment
  console.log('\nclassification alignment (Advanced -> Advance)');
  await step(
    "student_subject_levels data: 'Advanced' -> 'Advance'",
    `SELECT COUNT(*) AS needed FROM dbo.student_subject_levels WHERE level = 'Advanced'`,
    `UPDATE dbo.student_subject_levels SET level = 'Advance' WHERE level = 'Advanced'`
  );
  await dropColumnCheck('student_subject_levels', 'level', 'CK_ssl_level');
  await step(
    'CHECK on student_subject_levels.level',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.check_constraints WHERE name = 'CK_ssl_level' AND parent_object_id = OBJECT_ID('dbo.student_subject_levels')
     ) THEN 1 ELSE 0 END AS needed`,
    `ALTER TABLE dbo.student_subject_levels ADD CONSTRAINT CK_ssl_level
       CHECK (level IN ('Beginner','Intermediate','Advance'))`
  );

  // ------------------------------------------------ Phase 8: module opens
  //
  // "All modules completed" (spec Section 4b) needs a record that the student
  // actually opened each module. The existing module_reads table cannot serve:
  // its resource_id points at the legacy subject_resources, not at `modules`.
  // Writing module ids into it would silently mix two id spaces.
  console.log('\nPhase 8 — module opens');
  await step(
    'table student_module_reads',
    `SELECT CASE WHEN OBJECT_ID('dbo.student_module_reads', 'U') IS NULL THEN 1 ELSE 0 END AS needed`,
    `CREATE TABLE dbo.student_module_reads (
       id INT IDENTITY(1,1) PRIMARY KEY,
       student_id INT NOT NULL,
       module_id INT NOT NULL,
       subject_id INT NOT NULL,
       first_opened_at DATETIME2 NOT NULL CONSTRAINT df_smr_first DEFAULT DATEADD(hour, 8, GETUTCDATE()),
       last_opened_at DATETIME2 NOT NULL CONSTRAINT df_smr_last DEFAULT DATEADD(hour, 8, GETUTCDATE()),
       CONSTRAINT fk_smr_student FOREIGN KEY (student_id) REFERENCES dbo.users(id),
       CONSTRAINT fk_smr_module FOREIGN KEY (module_id) REFERENCES dbo.modules(id) ON DELETE CASCADE
     )`
  );
  await step(
    'unique index on (student_id, module_id)',
    `SELECT CASE WHEN NOT EXISTS (
       SELECT 1 FROM sys.indexes WHERE name = 'uq_smr_student_module' AND object_id = OBJECT_ID('dbo.student_module_reads')
     ) THEN 1 ELSE 0 END AS needed`,
    // One row per student per module: the guard against a double-open creating a
    // second row and inflating the completion count.
    `CREATE UNIQUE INDEX uq_smr_student_module ON dbo.student_module_reads (student_id, module_id)`
  );

  console.log('');
  console.log(`applied: ${results.applied}   skipped: ${results.skipped}   failed: ${results.failed}`);
  if (results.failed) {
    console.log('\nOne or more steps failed. Nothing else was rolled back — re-run after fixing.');
    process.exit(1);
  }
  process.exit(0);
}

main().catch((error) => {
  console.error('Migration aborted:', error.message);
  process.exit(1);
});
